// Replies built from two different literal shapes (a result or a failure),
// returned through one declared interface whose members are optional.
function success(id, result) {
  return { version: "1", id, result: result === undefined ? null : result };
}
function failed(id, code, message) {
  return { version: "1", id, failure: { code, message } };
}
export function describe(reply) {
  const failure = reply.failure;
  return failure === undefined ? `result ${JSON.stringify(reply.result)}` : `failure ${failure.code}: ${failure.message}`;
}
export class Dispatcher {
  async dispatch(call) {
    if (call.method === "sum") return success(call.id, (call.args ?? []).reduce((a, b) => a + b, 0));
    if (call.method === "echo") return success(call.id, call.args);
    return failed(call.id, -32601, "unknown method " + call.method);
  }
  async reject(id, message) {
    return failed(id, -32602, message);
  }
  replyNow(call) {
    return call.method === "sum" ? success(call.id, 0) : failed(call.id, -32600, "not now");
  }
}
